        const IRAQ_ASSETS = { dem: 'assets/iraq-dem.png', sat2: 'assets/iraq-sat-2k.jpg', sat4: 'assets/iraq-sat-4k.jpg', mask: 'assets/iraq-mask.png', clouds: 'assets/clouds.png' };
