                this.W = 10; this.H = this.W * this.sy / (this.sx * Math.cos(33.3 * Math.PI / 180));
                this.HS = 0.85;
                this.yaw = 0; this.pitch = 1.0; this.dist = 12;
                // The shamal: Iraq's north-westerly wind (x = east, z = south). Afternoon sun from the south-west.
                this.wind = [0.7071, 0.7071];
                this.sun = [-0.5, 0.68, 0.53];
                this.eye = [0, 10, 10];
                this.rows = []; this.byName = {}; this.max = 0; this.mine = ''; this.leader = '';
                this.missiles = []; this.impacts = []; this.nextShot = 0; this.salvo = [];
