                    const m = ss(-0.05, 0.9, sd(lon, lat));
                    const ridge = 1 - Math.abs(this._fbm(lon * 2.2, lat * 2.2, 4) * 2 - 1);
                    let h = 0.03 + 0.05 * this._fbm(lon * 1.5 + 9, lat * 1.5, 3);
