                    h += m * (0.25 + 0.75 * ridge * ridge) * (0.7 + 0.3 * ss(0, 2, sd(lon, lat)));
                    h += 0.28 * g(lon, lat, 41.85, 36.37, 0.55, 0.07) + 0.12 * g(lon, lat, 44.3, 34.55, 0.9, 0.08) * (0.6 + 0.4 * ridge);
