                            c = mix(c, [150, 112, 78], ss(0.62, 0.82, this._fbm(lon * 5 + 3, lat * 5, 3)) * 0.6);
                            c = mix(c, [160, 152, 106], ss(34.6, 36.6, lat) * 0.75);
