                    ox.strokeStyle = 'rgba(255,90,60,.22)'; ox.lineWidth = 11; ox.stroke();
                    ox.strokeStyle = 'rgba(255,190,150,.95)'; ox.lineWidth = 2.6; ox.stroke();
