                // shadows drifting with the wind and sun glints on rivers, marshes and the Gulf.
                this.pTer = this._prog(
                    'attribute vec3 p;attribute vec2 t;attribute vec3 q;uniform mat4 m;varying vec2 v;varying float d;varying vec3 wp;varying vec3 wn;void main(){v=t;d=length(p.xz);wp=p;wn=q;gl_Position=m*vec4(p,1.);}',
                    'precision mediump float;uniform sampler2D s;uniform sampler2D k;uniform sampler2D z;uniform float r;uniform float T;uniform vec2 W;uniform vec3 E;uniform vec3 L;uniform float Q;uniform vec4 CL[12];uniform vec4 FL;uniform vec4 WX;varying vec2 v;varying float d;varying vec3 wp;varying vec3 wn;'
                    + 'float gust(vec2 a){return pow(.5+.5*sin(dot(a,W)*.55-T*.9),3.)*(.7+.3*sin(dot(a,vec2(-W.y,W.x))*1.3+T*.3));}'
                    + 'void main(){vec3 c=texture2D(s,v).rgb;vec3 mk=texture2D(k,v).rgb*Q;vec3 n=normalize(wn);float dif=max(dot(n,L),0.);float I=WX.x;c*=(.52+.58*dif)*mix(.62,1.,I);'
                    + 'float g=gust(wp.xz)*WX.w;float rp=.5+.5*sin(dot(wp.xz,W)*70.-T*7.+sin(wp.x*23.+wp.z*9.)*2.);c+=mk.g*g*(.05+.08*rp)*vec3(.6,.8,.35);'
                    // cloud shadows and wet ground under the real clouds (x, z, radius, rain*9 + shadow)
                    + 'float nz=texture2D(z,v*7.+W*T*.004).r,sh=0.,wet=0.;for(int i=0;i<12;i++){vec4 q=CL[i];if(q.z<=0.)continue;float dd=length(wp.xz-q.xy)/q.z+(nz-.5)*.45;float kk=1.-smoothstep(.3,1.,dd);sh=max(sh,kk*fract(q.w));wet=max(wet,kk*floor(q.w)/9.);}'
                    + 'c*=1.-sh;c=mix(c,c*vec3(.66,.72,.78),wet*.7);'
                    + 'if(WX.z>.5){float cl=texture2D(z,v*2.3-W*T*.006).r*.62+texture2D(z,v*5.1-W*T*.009+.3).r*.38;c*=1.-.24*smoothstep(.58,.8,cl)*Q;}'
                    + 'if(mk.r>.02){vec2 fl=W*T*.02*(.6+WX.w);float h1=texture2D(z,v*38.+fl).r,h2=texture2D(z,v*61.-fl.yx*1.3).r;vec3 n2=normalize(vec3((h1-.5)*(.9+wet),1.,(h2-.5)*(.9+wet)));vec3 vd=normalize(E-wp);float sp=pow(max(dot(reflect(-L,n2),vd),0.),40.)*I*(1.-sh);float fr=pow(1.-max(vd.y,0.),3.);vec3 wc=mix(c*vec3(.8,.95,1.05),vec3(.1,.22,.3),.3)+vec3(1.,.93,.78)*sp*1.4+vec3(.5,.62,.7)*fr*.25;c=mix(c,wc,mk.r);}'
                    + 'c=mix(c,vec3(.78,.62,.42)*mix(.7,1.,I),WX.y*(.4+.25*nz));'
                    + 'c+=vec3(.72,.78,1.)*FL.w*(.12+.9*(1.-smoothstep(0.,FL.z,length(wp.xz-FL.xy))));'
                    + 'c=mix(c,mix(vec3(.25,.28,.32),vec3(.55,.62,.66),I),smoothstep(10.,30.,length(E-wp))*.28);'
                    + 'float e=smoothstep(0.,.07,v.x)*smoothstep(1.,.93,v.x)*smoothstep(0.,.07,v.y)*smoothstep(1.,.93,v.y);c*=1.-smoothstep(3.5,7.5,d)*.4;gl_FragColor=vec4(c,e*r);}');
